import pandas as pd, re, json, os

logs = pd.read_csv('/app/data/test_center_logs.csv')

codebooks = {}
for p in ['P1_POWER','P2_CTRL','P3_RF']:
    df = pd.read_csv(f'/app/data/codebook_{p}.csv')
    df = df.sort_values('code').reset_index(drop=True)
    entries = []
    for _, row in df.iterrows():
        kws = []
        if pd.notna(row.get('keywords_examples')):
            for part in str(row['keywords_examples']).split(','):
                kw = part.strip()
                if kw:
                    kws.append(kw)
        if pd.notna(row.get('standard_label')):
            for tok in re.findall(r'[A-Za-z]{1,4}\d+|[A-Za-z0-9]+_[A-Za-z0-9_]+', str(row['standard_label'])):
                if tok not in kws:
                    kws.append(tok)
        entries.append({
            'code': row['code'],
            'label': row['standard_label'],
            'station_scope': str(row.get('station_scope') or ''),
            'keywords': kws,
            'category_lv1': row.get('category_lv1','')
        })
    codebooks[p] = entries

syn_map = {
    '开路': 'open',
    '短路': 'short',
    '连锡': 'short',
    '桥连': 'short',
    '虚焊': 'cold solder',
    '浮高': 'cold solder',
    '冷焊': 'cold solder',
    '接触不良': 'fixture contact',
    '治具': 'fixture',
    '探针': 'pogo probe',
    '重插': 'reseat',
    '复测': 'retest',
    '烧录失败': 'flash fail program fail write fail',
    '写入失败': 'write fail',
    '编程失败': 'program fail',
    '校验失败': 'checksum verify fail',
    '校验': 'checksum verify',
    'CRC': 'checksum',
    '版本不符': 'version mismatch',
    '启动失败': 'boot fail',
    '卡死': 'stuck boot fail',
    '少件': 'missing',
    '缺件': 'missing',
    '反向': 'reversed polarity',
    '反装': 'reversed polarity',
    '极性': 'polarity',
    '漏电': 'leakage hipot',
    '绝缘不良': 'leakage hipot',
    '静电': 'ESD',
    '插拔': 'connector wear',
    '助焊剂': 'contamination residue',
    '污染': 'contamination',
    '清洗': 'contamination',
    '功耗高': 'current high',
    '静态电流': 'current high',
    '电流偏高': 'current high',
    '电流过高': 'current high',
}

split_re = re.compile(r'\s*(?:；|;|\s\+\s|\s&\s|\s+and\s+|\s+then\s+|\s+\+|\+\s|\s+&|&\s)\s*', re.I)

cjk_re = re.compile(r'[\u4e00-\u9fff]')


def is_specific_token(tok: str) -> bool:
    return bool(re.search(r'\d', tok) or '_' in tok)


def contains_keyword(text_lower: str, text_raw: str, kw: str) -> bool:
    if not kw:
        return False
    kw_strip = kw.strip()
    if not kw_strip:
        return False
    if cjk_re.search(kw_strip):
        return kw_strip in text_raw
    return kw_strip.lower() in text_lower


def augment_text(raw_text: str, extra_text: str = '') -> str:
    text_raw = raw_text or ''
    text_lower = (text_raw + ' ' + (extra_text or '')).lower()
    for ch, eng in syn_map.items():
        if ch in text_raw:
            text_lower += ' ' + eng
    if re.search(r'\bOS\b', text_raw, re.I):
        text_lower += ' open short'
    return text_lower


def entry_has_specific(entry):
    return any(is_specific_token(kw) for kw in entry['keywords'])


def score_entry(entry, text_lower_aug, text_lower_raw, text_raw, station: str):
    score = 0.0
    matched = []
    matched_general = 0
    matched_specific = 0
    for kw in entry['keywords']:
        if not kw:
            continue
        in_raw = contains_keyword(text_lower_raw, text_raw, kw)
        in_aug = False if in_raw else contains_keyword(text_lower_aug, text_raw, kw)
        if in_raw or in_aug:
            specific = is_specific_token(kw)
            if in_raw:
                weight = 3.0 if specific else 1.0
            else:
                weight = 1.5 if specific else 0.5
            score += weight
            matched.append(kw)
            if specific:
                matched_specific += 1
            else:
                matched_general += 1
    # Penalize if only specific matches (likely from test_item) without defect keyword
    if matched_general == 0 and matched_specific > 0:
        score *= 0.4
    # Penalize entries with expected specific tokens but none matched
    if entry_has_specific(entry) and matched_specific == 0:
        score *= 0.3

    scope = entry.get('station_scope','') or ''
    station_match = False
    if station:
        scopes = [s.strip() for s in scope.split(';') if s.strip()]
        if scopes:
            if station in scopes:
                score += 0.5
                station_match = True
            else:
                score -= 0.2
                if score < 0:
                    score = 0.0
    return score, matched, station_match

results = []

for _, row in logs.iterrows():
    record_id = row['record_id']
    product_id = row['product_id']
    station = row['station']
    engineer_id = row['engineer_id']
    raw_reason = row['raw_reason_text']
    if pd.isna(raw_reason):
        raw_reason = ''
    raw_reason_str = str(raw_reason)

    extra_parts = []
    for field in ['test_item','fail_code']:
        val = row.get(field, '')
        if pd.notna(val) and str(val).strip():
            extra_parts.append(str(val))
    extra_text = ' '.join(extra_parts)

    segments = [raw_reason_str]
    if raw_reason_str and split_re.search(raw_reason_str):
        parts = [p.strip() for p in split_re.split(raw_reason_str) if p and p.strip()]
        seen = set()
        segs = []
        for p in parts:
            if p not in seen:
                seen.add(p)
                segs.append(p)
        if segs:
            segments = segs

    normalized_segments = []
    best_any = None

    for seg in segments:
        text_lower_aug = augment_text(seg, extra_text)
        text_lower_raw = augment_text(seg, '')
        text_raw = seg
        if not text_raw.strip():
            continue
        best = None
        second = None
        for entry in codebooks[product_id]:
            score, matched, station_match = score_entry(entry, text_lower_aug, text_lower_raw, text_raw, station)
            if best is None or score > best[0] or (score == best[0] and len(matched) > len(best[2])) or (score == best[0] and len(matched)==len(best[2]) and entry['code'] < best[1]['code']):
                second = best
                best = (score, entry, matched, station_match)
            elif second is None or score > second[0]:
                second = (score, entry, matched, station_match)
        if best_any is None or (best and best[0] > best_any[0]):
            best_any = best

        score = best[0] if best else 0.0
        second_score = second[0] if second else 0.0

        if score < 1.5:
            continue

        base = 0.35 + 0.08 * score
        if best[3]:
            base += 0.05
        gap = score - second_score
        if gap < 1.0:
            base -= 0.05
        if gap < 0.5:
            base -= 0.05
        conf = max(0.45, min(0.95, base))

        matched_tokens = ', '.join(best[2][:4]) if best[2] else ''
        rationale = 'Matched keywords: ' + matched_tokens if matched_tokens else 'Matched keyword signal'
        if best[3]:
            rationale += '; station in scope'

        normalized_segments.append({
            'span_text': seg,
            'pred_code': best[1]['code'],
            'pred_label': best[1]['label'],
            'confidence': round(float(conf), 3),
            'rationale': rationale
        })

    if not normalized_segments:
        if best_any and best_any[0] >= 1.0:
            score = best_any[0]
            base = 0.30 + 0.07 * score
            if best_any[3]:
                base += 0.03
            conf = max(0.4, min(0.9, base))
            matched_tokens = ', '.join(best_any[2][:4]) if best_any[2] else ''
            rationale = 'Weak match; keywords: ' + matched_tokens if matched_tokens else 'Weak match based on limited keywords'
            normalized_segments.append({
                'span_text': raw_reason_str,
                'pred_code': best_any[1]['code'],
                'pred_label': best_any[1]['label'],
                'confidence': round(float(conf), 3),
                'rationale': rationale
            })
        else:
            conf = 0.2 if raw_reason_str.strip() else 0.1
            rationale = 'No strong keyword match in codebook'
            normalized_segments.append({
                'span_text': raw_reason_str,
                'pred_code': 'UNKNOWN',
                'pred_label': '',
                'confidence': round(float(conf), 3),
                'rationale': rationale
            })

    for i, seg in enumerate(normalized_segments, start=1):
        seg['segment_id'] = f"{record_id}-S{i}"

    results.append({
        'record_id': record_id,
        'product_id': product_id,
        'station': station,
        'engineer_id': engineer_id,
        'raw_reason_text': raw_reason_str,
        'normalized': normalized_segments
    })

os.makedirs('/app/output', exist_ok=True)
with open('/app/output/solution.json','w', encoding='utf-8') as f:
    json.dump({'records': results}, f, ensure_ascii=False)

print('written', len(results))
